#!/usr/bin/env node
'use strict';

/**
 * Build public/assets/icons.svg: one SVG sprite holding only the icons the
 * interface uses, taken from the Lucide set (ISC licence).
 *
 *   node scripts/build-icons.js
 *
 * Use in a template:
 *   <svg class="icon" aria-hidden="true"><use href="/assets/icons.svg#building"></use></svg>
 *
 * To add an icon, add a line to ICONS (name used in templates -> Lucide file
 * name) and run this script again. The generated file is committed.
 */

const fs = require('node:fs');
const path = require('node:path');

const ICONS = {
  // navigation
  dashboard: 'layout-dashboard',
  building: 'building-2',
  users: 'users',
  interactions: 'messages-square',
  briefcase: 'briefcase',
  calendar: 'calendar',
  tasks: 'list-checks',
  reports: 'chart-column',
  outcomes: 'award',
  opportunities: 'handshake',
  import: 'upload',
  settings: 'settings',
  shield: 'shield',
  history: 'history',
  trash: 'trash-2',
  // actions
  plus: 'plus',
  search: 'search',
  filter: 'list-filter',
  edit: 'pencil',
  download: 'download',
  print: 'printer',
  more: 'ellipsis',
  close: 'x',
  check: 'check',
  restore: 'undo-2',
  merge: 'git-merge',
  save: 'bookmark',
  external: 'arrow-up-right',
  refresh: 'refresh-cw',
  menu: 'menu',
  logout: 'log-out',
  // indicators
  'chevron-down': 'chevron-down',
  'chevron-right': 'chevron-right',
  'chevron-left': 'chevron-left',
  'sort-up': 'arrow-up',
  info: 'info',
  warning: 'triangle-alert',
  error: 'circle-alert',
  success: 'circle-check',
  clock: 'clock',
  mail: 'mail',
  phone: 'phone',
  link: 'link',
  user: 'user',
  star: 'star',
  tag: 'tag',
  note: 'sticky-note',
  bell: 'bell',
  lock: 'lock',
  globe: 'globe',
};

const sourceDir = path.join(__dirname, '..', 'node_modules', 'lucide-static', 'icons');
const outFile = path.join(__dirname, '..', 'public', 'assets', 'icons.svg');

const symbols = Object.entries(ICONS).map(([name, file]) => {
  const svgPath = path.join(sourceDir, `${file}.svg`);
  if (!fs.existsSync(svgPath)) throw new Error(`Lucide has no icon named "${file}" (wanted for "${name}")`);
  const inner = fs
    .readFileSync(svgPath, 'utf8')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<svg[\s\S]*?>/, '')
    .replace(/<\/svg>/, '')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .join('');
  return `  <symbol id="${name}" viewBox="0 0 24 24">${inner}</symbol>`;
});

const sprite = [
  '<!-- Generated by scripts/build-icons.js. Icons: Lucide (ISC licence), https://lucide.dev -->',
  '<svg xmlns="http://www.w3.org/2000/svg" style="display:none">',
  ...symbols,
  '</svg>',
  '',
].join('\n');

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, sprite);
console.log(
  `Wrote ${Object.keys(ICONS).length} icons to ${path.relative(process.cwd(), outFile)} (${sprite.length} bytes)`
);
